import numpy as np, pandas as pd
from scipy.signal import savgol_filter
from scipy.optimize import curve_fit
def L(x,h,c,w): return h/(1+((x-c)/(w/2))**2)
for f in ['Au','Cu']:
    d=pd.read_csv(f'spectrum_{f}.csv'); x=d.shift_cm1.values; y=d.intensity.values
    print('=====',f)
    # local linear baseline fits
    def win(lo,hi,p0,nb=2):
        m=(x>lo)&(x<hi); xx=x[m]; yy=y[m]
        def fn(x,*p):
            return L(x,*p[:3])+p[3]+p[4]*(x-1500)
        try:
            p,c=curve_fit(fn,xx,yy,p0=p0+[np.median(yy),0]); e=np.sqrt(np.diag(c))
            res=yy-fn(xx,*p)
            print(f'win {lo}-{hi}: h={p[0]:.1f}+-{e[0]:.1f} c={p[1]:.1f}+-{e[1]:.1f} w={p[2]:.1f}+-{e[2]:.1f} rms={res.std():.1f}')
            return p,res.std()
        except Exception as ex: print('fail',ex)
    for nm,lo,hi,p0 in [('D',1250,1450,[20,1345,30]),('G',1500,1680,[20,1580,20]),('2D',2550,2850,[40,2690,35]),('2436',2350,2520,[20,2436,40]),('2326',2290,2360,[30,2328,5]),('Dp',1590,1700,[5,1620,15])]:
        print(nm,end=' '); win(lo,hi,p0)
    # noise
    m=(x>1650)&(x<2250); xx=x[m]; r=y[m]-np.polyval(np.polyfit(xx,y[m],3),xx); print('noise rms 1650-2250',r.std())
    print('points near 2326:',[(round(a,1),b) for a,b in zip(x,y) if 2310<a<2345])
    print('points near 1350 (Cu D check): mean 1330-1370',y[(x>1330)&(x<1370)].mean(),'vs 1270-1300 and 1400-1430',y[(x>1270)&(x<1300)].mean(),y[(x>1400)&(x<1430)].mean())
EOF
